// Theme choices stay in the URL; no tracking or persistent preference storage.
(()=>{const choices=['collector','armory','museum','poke-dex','poke-league','poke-retro','poke-energy','poke-holo','poke-island'];const requested=new URLSearchParams(location.search).get('theme');document.documentElement.dataset.theme=choices.includes(requested)?requested:'poke-island';document.addEventListener('DOMContentLoaded',()=>{const button=document.querySelector('#themeToggle');if(!button)return;const update=()=>{const dark=document.documentElement.dataset.theme==='poke-holo';button.textContent=dark?'☀ Dag':'☾ Nacht';button.setAttribute('aria-pressed',String(dark))};update();button.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='poke-holo'?'poke-island':'poke-holo';const url=new URL(location.href);url.searchParams.set('theme',document.documentElement.dataset.theme);history.replaceState({},'',url);update()})})})();
